"""CLI entry point with multiple subcommands."""

import click
from cli_tool.commands.build import build
from cli_tool.commands.deploy import deploy
from cli_tool.commands.info import info


@click.group()
@click.option("--verbose", "-v", is_flag=True, help="Enable verbose output.")
@click.option("--config", "-c", type=click.Path(exists=True), default=None, help="Path to config file.")
@click.version_option(version="0.1.0")
@click.pass_context
def cli(ctx, verbose, config):
    """CLI tool - a sample command-line application."""
    ctx.ensure_object(dict)
    ctx.obj["verbose"] = verbose
    ctx.obj["config"] = config


cli.add_command(build)
cli.add_command(deploy)
cli.add_command(info)


if __name__ == "__main__":
    cli()

"""Build command subcommand."""

import click


@click.command()
@click.argument("target", type=click.Choice(["debug", "release"]), default="release")
@click.option("--output", "-o", type=click.Path(), default="./dist", help="Output directory.")
@click.option("--jobs", "-j", type=int, default=1, help="Number of parallel jobs.")
@click.option("--force", "-f", is_flag=True, help="Force rebuild.")
@click.pass_context
def build(ctx, target, output, jobs, force):
    """Build the project."""
    verbose = ctx.obj.get("verbose", False)
    click.echo(f"Building target: {target}")
    click.echo(f"Output directory: {output}")
    click.echo(f"Parallel jobs: {jobs}")
    if force:
        click.echo("Force rebuild enabled.")
    if verbose:
        click.echo("Verbose mode on.")

"""Deploy command subcommand."""

import click


@click.command()
@click.argument("environment", type=click.Choice(["staging", "production"]))
@click.option("--region", "-r", type=str, default="us-east-1", help="Deployment region.")
@click.option("--dry-run", is_flag=True, help="Preview changes without applying.")
@click.option("--tag", "-t", type=str, default=None, help="Tag to deploy.")
@click.pass_context
def deploy(ctx, environment, region, dry_run, tag):
    """Deploy to an environment."""
    verbose = ctx.obj.get("verbose", False)
    click.echo(f"Deploying to: {environment}")
    click.echo(f"Region: {region}")
    if tag:
        click.echo(f"Tag: {tag}")
    if dry_run:
        click.echo("Dry run - no changes applied.")
    if verbose:
        click.echo("Verbose mode on.")

"""Info command subcommand."""

import click
import platform


@click.command()
@click.option("--all", "-a", is_flag=True, help="Show all available info.")
@click.option("--json", "-j", "as_json", is_flag=True, help="Output as JSON.")
@click.pass_context
def info(ctx, all, as_json):
    """Show system and tool information."""
    verbose = ctx.obj.get("verbose", False)
    click.echo(f"CLI tool version: 0.1.0")
    click.echo(f"Python: {platform.python_version()}")
    click.echo(f"Platform: {platform.platform()}")
    if all:
        click.echo(f"Config file: {ctx.obj.get('config', 'None')}")
        click.echo(f"Verbose: {verbose}")
